/* compute only, no xor, no transpose store of useful output — sink the state */
volatile uint64_t sink;

void chacha20_compute_only(size_t len, const uint32_t key[8], uint32_t ctr0, const uint32_t nonce[3]) {
    size_t full = (len / 512) * 512;
    uint32_t ctr = ctr0;
    __m256i c0 = _mm256_set1_epi32(0x61707865);
    __m256i c1 = _mm256_set1_epi32(0x3320646e);
    __m256i c2 = _mm256_set1_epi32(0x79622d32);
    __m256i c3 = _mm256_set1_epi32(0x6b206574);
    __m256i k0 = _mm256_set1_epi32(key[0]);
    __m256i k1 = _mm256_set1_epi32(key[1]);
    __m256i k2 = _mm256_set1_epi32(key[2]);
    __m256i k3 = _mm256_set1_epi32(key[3]);
    __m256i k4 = _mm256_set1_epi32(key[4]);
    __m256i k5 = _mm256_set1_epi32(key[5]);
    __m256i k6 = _mm256_set1_epi32(key[6]);
    __m256i k7 = _mm256_set1_epi32(key[7]);
    __m256i n0 = _mm256_set1_epi32(nonce[0]);
    __m256i n1 = _mm256_set1_epi32(nonce[1]);
    __m256i n2 = _mm256_set1_epi32(nonce[2]);
    __m256i acc = _mm256_setzero_si256();
    for (size_t off = 0; off < full; off += 512) {
        __m256i x0=c0,x1=c1,x2=c2,x3=c3;
        __m256i x4=k0,x5=k1,x6=k2,x7=k3;
        __m256i x8=k4,x9=k5,x10=k6,x11=k7;
        __m256i x12=_mm256_add_epi32(_mm256_set1_epi32(ctr), _mm256_set_epi32(7,6,5,4,3,2,1,0));
        __m256i x13=n0,x14=n1,x15=n2;
        for (int r=0;r<10;r++) {
            QR(&x0,&x4,&x8,&x12); QR(&x1,&x5,&x9,&x13);
            QR(&x2,&x6,&x10,&x14); QR(&x3,&x7,&x11,&x15);
            QR(&x0,&x5,&x10,&x15); QR(&x1,&x6,&x11,&x12);
            QR(&x2,&x7,&x8,&x13); QR(&x3,&x4,&x9,&x14);
        }
        acc = _mm256_xor_si256(acc, x0);
        acc = _mm256_xor_si256(acc, x12);
        ctr += 8;
    }
    sink = (uint64_t)_mm256_extract_epi64(acc, 0);
}

static double now() {
    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec/1e9;
}

int main() {
    size_t n = (40ull*1000*1024/512)*512;
    uint8_t *in = aligned_alloc(64, n);
    uint8_t *out = aligned_alloc(64, n);
    memset(in, 1, n);
    uint32_t key[8] = {1,2,3,4,5,6,7,8};
    uint32_t nonce[3] = {9,10,11};
    chacha20_8x(out, in, n, key, 0, nonce);
    int N=3;
    double t0 = now();
    for (int i=0;i<N;i++) chacha20_8x(out, in, n, key, 0, nonce);
    double t1 = now();
    printf("full xor: %.2f ms  thr=%.0f MB/s\n", (t1-t0)/N*1000, n*N/(t1-t0)/1e6);

    chacha20_compute_only(n, key, 0, nonce);
    t0 = now();
    for (int i=0;i<N;i++) chacha20_compute_only(n, key, 0, nonce);
    t1 = now();
    printf("compute only: %.2f ms  thr=%.0f MB/s  sink=%llu\n", (t1-t0)/N*1000, n*N/(t1-t0)/1e6, (unsigned long long)sink);

    /* memcpy bandwidth */
    t0 = now();
    for (int i=0;i<N;i++) memcpy(out, in, n);
    t1 = now();
    printf("memcpy: %.2f ms  thr=%.0f MB/s\n", (t1-t0)/N*1000, n*N/(t1-t0)/1e6);

    /* read+write xor bandwidth */
    t0 = now();
    for (int i=0;i<N;i++) {
        __m256i *op = (__m256i*)out;
        const __m256i *ip = (const __m256i*)in;
        __m256i k = _mm256_set1_epi8(0x5a);
        for (size_t j=0;j<n/32;j++) op[j] = _mm256_xor_si256(ip[j], k);
    }
    t1 = now();
    printf("xor bandwidth: %.2f ms  thr=%.0f MB/s\n", (t1-t0)/N*1000, n*N/(t1-t0)/1e6);
    return 0;
}
EOF
