#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <immintrin.h>

static double now() {
    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec/1e9;
}

typedef struct { uint8_t *a, *b; size_t n; } Job;
void *xor_job(void *p) {
    Job *j = p;
    __m256i k = _mm256_set1_epi8(0x5a);
    size_t cnt = j->n / 32;
    __m256i *op = (__m256i*)j->b;
    const __m256i *ip = (const __m256i*)j->a;
    for (size_t i = 0; i < cnt; i++) op[i] = _mm256_xor_si256(ip[i], k);
    return NULL;
}
void *copy_job(void *p) {
    Job *j = p;
    memcpy(j->b, j->a, j->n);
    return NULL;
}
void *write_job(void *p) {
    Job *j = p;
    __m256i k = _mm256_set1_epi8(0x5a);
    size_t cnt = j->n / 32;
    __m256i *op = (__m256i*)j->b;
    for (size_t i = 0; i < cnt; i++) op[i] = k;
    return NULL;
}

int main() {
    size_t total = 40ull * 1000 * 1024;
    int threads_list[] = {1,2,4,6};
    uint8_t *a = aligned_alloc(64, total);
    uint8_t *b = aligned_alloc(64, total);
    memset(a, 1, total);
    memset(b, 2, total);
    for (int ti = 0; ti < 4; ti++) {
        int T = threads_list[ti];
        size_t chunk = total / T;
        pthread_t th[8];
        Job jobs[8];
        /* warmup */
        for (int i = 0; i < T; i++) {
            jobs[i].a = a + i*chunk; jobs[i].b = b + i*chunk; jobs[i].n = (i==T-1)? total-i*chunk : chunk;
        }
        for (int i = 0; i < T; i++) pthread_create(&th[i], NULL, copy_job, &jobs[i]);
        for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
        int N = 5;
        double t0 = now();
        for (int rep = 0; rep < N; rep++) {
            for (int i = 0; i < T; i++) pthread_create(&th[i], NULL, copy_job, &jobs[i]);
            for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
        }
        double t1 = now();
        printf("memcpy T=%d: %.2f ms thr=%.0f MB/s\n", T, (t1-t0)/N*1000, total*N/(t1-t0)/1e6);

        t0 = now();
        for (int rep = 0; rep < N; rep++) {
            for (int i = 0; i < T; i++) pthread_create(&th[i], NULL, xor_job, &jobs[i]);
            for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
        }
        t1 = now();
        printf("xor T=%d: %.2f ms thr=%.0f MB/s\n", T, (t1-t0)/N*1000, total*N/(t1-t0)/1e6);

        t0 = now();
        for (int rep = 0; rep < N; rep++) {
            for (int i = 0; i < T; i++) pthread_create(&th[i], NULL, write_job, &jobs[i]);
            for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
        }
        t1 = now();
        printf("write T=%d: %.2f ms thr=%.0f MB/s\n", T, (t1-t0)/N*1000, total*N/(t1-t0)/1e6);
    }
    /* single thread large write no thread create overhead */
    double t0 = now();
    int N=5;
    for (int i=0;i<N;i++) memset(b, 0x5a, total);
    double t1 = now();
    printf("memset 1T: %.2f ms thr=%.0f MB/s\n", (t1-t0)/N*1000, total*N/(t1-t0)/1e6);
    return 0;
}
