#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>

#define T 4

typedef struct {
    const uint8_t *in;
    uint8_t *out;
    size_t n;
    const uint8_t *key;
    const uint8_t *nonce;
    uint32_t counter;
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
} Job;

static void *worker(void *arg) {
    Job *j = arg;
    int outl = 0;
    EVP_EncryptInit_ex(j->ctx, j->cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(j->ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    /* We only want the keystream XOR, not the poly tag, so use plain EVP_chacha20.
       EVP_chacha20 nonce is 16 bytes: 4-byte counter LE + 12-byte nonce. */
    uint8_t iv[16];
    memcpy(iv, &j->counter, 4);
    memcpy(iv+4, j->nonce, 12);
    EVP_EncryptInit_ex(j->ctx, NULL, NULL, j->key, iv);
    EVP_EncryptUpdate(j->ctx, j->out, &outl, j->in, (int)j->n);
    return NULL;
}

static PyObject *encrypt_chacha(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt;
    if (!PyArg_ParseTuple(args, "y*y*y*", &key, &nonce, &pt)) return NULL;
    PyObject *out = PyBytes_FromStringAndSize(NULL, pt.len);
    if (!out) { PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); return NULL; }
    uint8_t *dst = (uint8_t*)PyBytes_AS_STRING(out);
    const uint8_t *src = pt.buf;
    const EVP_CIPHER *cipher = EVP_chacha20();

    size_t n = pt.len;
    size_t chunk = (n / 64 / T) * 64;
    pthread_t th[T];
    Job jobs[T];
    EVP_CIPHER_CTX *ctxs[T];
    for (int i = 0; i < T; i++) ctxs[i] = EVP_CIPHER_CTX_new();
    size_t start = 0;
    int launched = 0;
    for (int i = 0; i < T && start < n; i++) {
        size_t end = (i == T-1 || start + chunk >= n) ? n : start + chunk;
        jobs[i].in = src + start;
        jobs[i].out = dst + start;
        jobs[i].n = end - start;
        jobs[i].key = key.buf;
        jobs[i].nonce = nonce.buf;
        jobs[i].counter = (uint32_t)(start / 64);
        jobs[i].ctx = ctxs[i];
        jobs[i].cipher = cipher;
        pthread_create(&th[i], NULL, worker, &jobs[i]);
        launched++;
        start = end;
    }
    for (int i = 0; i < launched; i++) pthread_join(th[i], NULL);
    for (int i = 0; i < T; i++) EVP_CIPHER_CTX_free(ctxs[i]);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    return out;
}

static PyMethodDef methods[] = {
    {"encrypt_chacha", encrypt_chacha, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef module = {PyModuleDef_HEAD_INIT, "chacha_ext", NULL, -1, methods};
PyMODINIT_FUNC PyInit_chacha_ext(void) { return PyModule_Create(&module); }
