#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>

#define MAX_T 8
static int T = 6;

typedef struct {
    pthread_t thread;
    pthread_mutex_t mtx;
    pthread_cond_t cv;
    int ready;       /* main -> worker: job posted */
    int done;        /* worker -> main: job finished */
    int stop;
    const uint8_t *in;
    uint8_t *out;
    size_t n;
    uint32_t counter;
    const uint8_t *key;
    const uint8_t *nonce;
    const uint8_t *otk;          /* 32 bytes, may be NULL to skip poly */
    EVP_CIPHER_CTX *cctx;
    EVP_MD_CTX *mdctx;           /* unused */
    /* poly1305 via EVP? We'll call the low-level by doing a second pass in python.
       Here we only do chacha, into the destination, and also compute nothing. */
    const EVP_CIPHER *cipher;
} Worker;

static Worker workers[MAX_T];
static int started = 0;

static void *worker_fn(void *arg) {
    Worker *w = arg;
    pthread_mutex_lock(&w->mtx);
    for (;;) {
        while (!w->ready && !w->stop) pthread_cond_wait(&w->cv, &w->mtx);
        if (w->stop) { pthread_mutex_unlock(&w->mtx); return NULL; }
        w->ready = 0;
        pthread_mutex_unlock(&w->mtx);

        if (w->n) {
            uint8_t iv[16];
            memcpy(iv, &w->counter, 4);
            memcpy(iv + 4, w->nonce, 12);
            int outl = 0;
            EVP_EncryptInit_ex(w->cctx, w->cipher, NULL, NULL, NULL);
            EVP_EncryptInit_ex(w->cctx, NULL, NULL, w->key, iv);
            EVP_EncryptUpdate(w->cctx, w->out, &outl, w->in, (int)w->n);
        }

        pthread_mutex_lock(&w->mtx);
        w->done = 1;
        pthread_cond_signal(&w->cv);
    }
}

static void ensure_started(void) {
    if (started) return;
    const EVP_CIPHER *cipher = EVP_chacha20();
    for (int i = 0; i < T; i++) {
        memset(&workers[i], 0, sizeof(Worker));
        pthread_mutex_init(&workers[i].mtx, NULL);
        pthread_cond_init(&workers[i].cv, NULL);
        workers[i].cctx = EVP_CIPHER_CTX_new();
        workers[i].cipher = cipher;
        pthread_create(&workers[i].thread, NULL, worker_fn, &workers[i]);
    }
    started = 1;
}

static PyObject *encrypt_chacha(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt;
    if (!PyArg_ParseTuple(args, "y*y*y*", &key, &nonce, &pt)) return NULL;
    ensure_started();
    PyObject *out = PyBytes_FromStringAndSize(NULL, pt.len);
    if (!out) goto fail;
    uint8_t *dst = (uint8_t *)PyBytes_AS_STRING(out);
    const uint8_t *src = pt.buf;
    size_t n = pt.len;
    size_t chunk = (n / 64 / T) * 64;
    if (chunk == 0) chunk = n;
    size_t start = 0;
    int used = 0;
    for (int i = 0; i < T && start < n; i++) {
        size_t end = (i == T - 1 || start + chunk >= n) ? n : start + chunk;
        Worker *w = &workers[i];
        pthread_mutex_lock(&w->mtx);
        w->in = src + start;
        w->out = dst + start;
        w->n = end - start;
        w->counter = (uint32_t)(start / 64);
        w->key = key.buf;
        w->nonce = nonce.buf;
        w->done = 0;
        w->ready = 1;
        pthread_cond_signal(&w->cv);
        pthread_mutex_unlock(&w->mtx);
        used++;
        start = end;
    }
    for (int i = 0; i < used; i++) {
        Worker *w = &workers[i];
        pthread_mutex_lock(&w->mtx);
        while (!w->done) pthread_cond_wait(&w->cv, &w->mtx);
        pthread_mutex_unlock(&w->mtx);
    }
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    return out;
fail:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt_chacha", encrypt_chacha, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef module = {PyModuleDef_HEAD_INIT, "chacha_ext", NULL, -1, methods};
PyMODINIT_FUNC PyInit_chacha_ext(void) { return PyModule_Create(&module); }
