/* 4-block AVX2 ChaCha20, column-round friendly, with a real transpose via
   unpack so the xor is vectorized. Measures single-thread throughput. */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>

static inline __m256i ROTL(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32-n));
}
#define QR(a,b,c,d) do { \
    a = _mm256_add_epi32(a, b); d = ROTL(_mm256_xor_si256(d, a), 16); \
    c = _mm256_add_epi32(c, d); b = ROTL(_mm256_xor_si256(b, c), 12); \
    a = _mm256_add_epi32(a, b); d = ROTL(_mm256_xor_si256(d, a), 8); \
    c = _mm256_add_epi32(c, d); b = ROTL(_mm256_xor_si256(b, c), 7); \
} while (0)

/* Transpose 4 ymm registers of 8 lanes? We do 8 blocks (two AVX2 of 4? )
   Simpler 8-wide as before but transpose with unpack instructions into 8 sequential blocks
   without scalar loops. */

static inline void transpose8(__m256i r[16], uint8_t *dst) {
    /* r[j] holds word j of 8 blocks. We want block b's 16 words contiguous.
       Do it in two 128-bit halves. */
    for (int half = 0; half < 2; half++) {
        __m128i w[16];
        for (int j = 0; j < 16; j++) {
            w[j] = half ? _mm256_extracti128_si256(r[j], 1) : _mm256_castsi256_si128(r[j]);
        }
        /* w[j] has words of 4 blocks. Transpose 16 x 4 -> 4 x 16. */
        __m128i t0, t1, t2, t3;
        /* process in groups of 4 words */
        __m128i o[4][4];
        for (int g = 0; g < 4; g++) {
            __m128i a = w[g*4+0], b = w[g*4+1], c = w[g*4+2], d = w[g*4+3];
            __m128i u0 = _mm_unpacklo_epi32(a, b);
            __m128i u1 = _mm_unpackhi_epi32(a, b);
            __m128i u2 = _mm_unpacklo_epi32(c, d);
            __m128i u3 = _mm_unpackhi_epi32(c, d);
            o[0][g] = _mm_unpacklo_epi64(u0, u2);
            o[1][g] = _mm_unpackhi_epi64(u0, u2);
            o[2][g] = _mm_unpacklo_epi64(u1, u3);
            o[3][g] = _mm_unpackhi_epi64(u1, u3);
        }
        uint8_t *base = dst + half * 4 * 64;
        for (int b = 0; b < 4; b++) {
            uint8_t *p = base + b * 64;
            for (int g = 0; g < 4; g++) _mm_storeu_si128((__m128i*)(p + g*16), o[b][g]);
        }
    }
}

void chacha8(uint8_t *out, const uint8_t *in, size_t len,
             const uint32_t key[8], uint32_t ctr, const uint32_t nonce[3]) {
    size_t full = (len / 512) * 512;
    __m256i c0=_mm256_set1_epi32(0x61707865), c1=_mm256_set1_epi32(0x3320646e);
    __m256i c2=_mm256_set1_epi32(0x79622d32), c3=_mm256_set1_epi32(0x6b206574);
    __m256i k0=_mm256_set1_epi32(key[0]), k1=_mm256_set1_epi32(key[1]);
    __m256i k2=_mm256_set1_epi32(key[2]), k3=_mm256_set1_epi32(key[3]);
    __m256i k4=_mm256_set1_epi32(key[4]), k5=_mm256_set1_epi32(key[5]);
    __m256i k6=_mm256_set1_epi32(key[6]), k7=_mm256_set1_epi32(key[7]);
    __m256i n0=_mm256_set1_epi32(nonce[0]), n1=_mm256_set1_epi32(nonce[1]), n2=_mm256_set1_epi32(nonce[2]);
    __m256i inc=_mm256_set_epi32(7,6,5,4,3,2,1,0);
    for (size_t off = 0; off < full; off += 512) {
        __m256i x0=c0,x1=c1,x2=c2,x3=c3,x4=k0,x5=k1,x6=k2,x7=k3;
        __m256i x8=k4,x9=k5,x10=k6,x11=k7;
        __m256i x12=_mm256_add_epi32(_mm256_set1_epi32(ctr), inc);
        __m256i x13=n0,x14=n1,x15=n2;
        __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7,s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;
        for (int r=0;r<10;r++) {
            QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15);
            QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14);
        }
        x0=_mm256_add_epi32(x0,s0); x1=_mm256_add_epi32(x1,s1); x2=_mm256_add_epi32(x2,s2); x3=_mm256_add_epi32(x3,s3);
        x4=_mm256_add_epi32(x4,s4); x5=_mm256_add_epi32(x5,s5); x6=_mm256_add_epi32(x6,s6); x7=_mm256_add_epi32(x7,s7);
        x8=_mm256_add_epi32(x8,s8); x9=_mm256_add_epi32(x9,s9); x10=_mm256_add_epi32(x10,s10); x11=_mm256_add_epi32(x11,s11);
