        __m256i rows[16]={x0,x1,x2,x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14,x15};
        uint8_t ks[512];
        transpose8(rows, ks);
        const __m256i *ip=(const __m256i*)(in+off);
        __m256i *op=(__m256i*)(out+off);
        const __m256i *kp=(const __m256i*)ks;
        for (int j=0;j<16;j++) op[j]=_mm256_xor_si256(ip[j], kp[j]);
        ctr += 8;
    }
}

static double now(){struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec/1e9;}

